let restore = () => {
  if (originalDescriptor && !original) {
    // No original function (e.g., getter-only), restore the descriptor as-is
    define(obj, accessName, originalDescriptor)
  } else if (originalDescriptor && descriptorSource !== obj) {
    // Original was on prototype, delete the own property we created
    delete obj[accessName as keyof T]
