import {
  createInternalSpy,
  isMockFunction,
  populateSpy,
  spies,
  SpyImpl,
  SpyInternal,
  SpyInternalImpl,
} from './internal.js'
import { assert, define, defineValue, descriptors, isType } from './utils.js'
import { SYMBOL_STATE } from './constants.js'

type Procedure = (...args: any[]) => any

type Methods<T> = {
  [K in keyof T]: T[K] extends Procedure ? K : never
}[keyof T]
type Getters<T> = {
  [K in keyof T]: T[K] extends Procedure ? never : K
}[keyof T]
type Constructors<T> = {
  [K in keyof T]: T[K] extends new (...args: any[]) => any ? K : never
}[keyof T]

let getDescriptor = (obj: any, method: string | symbol | number) => {
  let objDescriptor = Object.getOwnPropertyDescriptor(obj, method)
  if (objDescriptor) {
    return objDescriptor
  }
  let currentProto = Object.getPrototypeOf(obj)
  while (currentProto !== null) {
    const descriptor = Object.getOwnPropertyDescriptor(currentProto, method)
    if (descriptor) {
      return descriptor
    }
    currentProto = Object.getPrototypeOf(currentProto)
  }
}

let setPototype = (fn: any, val: any) => {
  if (val != null && typeof val === 'function' && val.prototype != null) {
    // inherit prototype, keep original prototype chain
    Object.setPrototypeOf(fn.prototype, val.prototype)
  }
}

export function internalSpyOn<T, K extends string & keyof T>(
  obj: T,
  methodName: K | { getter: K } | { setter: K },
  mock?: Procedure
): SpyInternalImpl<any[], any> {
  assert(
    !isType('undefined', obj),
    'spyOn could not find an object to spy upon'
  )

  assert(
    isType('object', obj) || isType('function', obj),
    'cannot spyOn on a primitive value'
  )

  let [accessName, accessType] = ((): [
    string | symbol | number,
    'value' | 'get' | 'set',
  ] => {
    if (!isType('object', methodName)) {
      return [methodName, 'value']
    }
    if ('getter' in methodName && 'setter' in methodName) {
      throw new Error('cannot spy on both getter and setter')
    }
    if ('getter' in methodName) {
      return [methodName.getter, 'get']
    }
    if ('setter' in methodName) {
      return [methodName.setter, 'set']
    }
    throw new Error('specify getter or setter to spy on')
  })()
  let originalDescriptor = getDescriptor(obj, accessName)

  assert(
    originalDescriptor || accessName in obj,
    `${String(accessName)} does not exist`
  )

  let ssr = false

  // vite ssr support - actual function is stored inside a getter
  if (
    accessType === 'value' &&
    originalDescriptor &&
    !originalDescriptor.value &&
    originalDescriptor.get
  ) {
    accessType = 'get'
    ssr = true
    mock = originalDescriptor.get!()
  }

  let original: Procedure | undefined

  if (originalDescriptor) {
    original = originalDescriptor[accessType]
  } else if (accessType !== 'value') {
    original = () => obj[accessName as keyof T]
  } else {
    original = obj[accessName as keyof T] as unknown as Procedure
  }

  if (original && isSpyFunction(original)) {
    original = original[SYMBOL_STATE].getOriginal()
  }

  let reassign = (cb: any) => {
    let { value, ...desc } = originalDescriptor || {
      configurable: true,
      writable: true,
    }
    if (accessType !== 'value') {
      delete desc.writable // getter/setter can't have writable attribute at all
    }
    ;(desc as PropertyDescriptor)[accessType] = cb
    define(obj, accessName, desc)
  }
  let restore = () =>
    originalDescriptor && !original
      ? define(obj, accessName, originalDescriptor)
      : reassign(original)

  if (!mock) mock = original

  // let fn: SpyInternal
  // if (origin && S in origin) {
  //   fn = origin as SpyInternal
  // } else {
  let spy = wrap(createInternalSpy(mock), mock)
  if (accessType === 'value') {
    setPototype(spy, original)
  }

  const state = spy[SYMBOL_STATE]
  defineValue(state, 'restore', restore)
  defineValue(state, 'getOriginal', () => (ssr ? original!() : original))
  defineValue(state, 'willCall', (newCb: Procedure) => {
    state.impl = newCb
    return spy
  })
  // }

  reassign(
    ssr
      ? () => {
          setPototype(spy, mock)
          return spy
        }
      : spy
  )

  spies.add(spy as any)
  return spy as any
}

const ignoreProperties = new Set<string | symbol>([
  'length',
  'name',
  'prototype',
])

function getAllProperties(original: Procedure) {
  const properties = new Set<string | symbol>()
  const descriptors: Record<string | symbol, PropertyDescriptor | undefined> =
    {}
  while (
    original &&
    original !== Object.prototype &&
    original !== Function.prototype
  ) {
    const ownProperties = [
      ...Object.getOwnPropertyNames(original),
      ...Object.getOwnPropertySymbols(original),
    ]
    for (const prop of ownProperties) {
      if (descriptors[prop] || ignoreProperties.has(prop)) {
        continue
      }
      properties.add(prop)
      descriptors[prop] = Object.getOwnPropertyDescriptor(original, prop)
    }
    original = Object.getPrototypeOf(original)
  }
  return {
    properties,
    descriptors,
  }
}

function wrap(mock: SpyInternal, original: Procedure | undefined): SpyInternal {
  if (
    !original ||
    // the original is already a spy, so it has all the properties
    SYMBOL_STATE in original
  ) {
    return mock
  }

  const { properties, descriptors } = getAllProperties(original)

  for (const key of properties) {
    const descriptor = descriptors[key]!
    const mockDescriptor = getDescriptor(mock, key)
    if (mockDescriptor) {
      continue
    }

    define(mock, key, descriptor)
  }
  return mock
}

// setters exist without getter, so we can check only getters
export function spyOn<T, S extends Getters<Required<T>>>(
  obj: T,
  methodName: { setter: S },
  mock?: (arg: T[S]) => void
): SpyImpl<[T[S]], void>
export function spyOn<T, G extends Getters<Required<T>>>(
  obj: T,
  methodName: { getter: G },
  mock?: () => T[G]
): SpyImpl<[], T[G]>
export function spyOn<T, M extends Constructors<Required<T>>>(
  object: T,
  method: M
): Required<T>[M] extends new (...args: infer A) => infer R
  ? SpyImpl<A, R>
  : never
export function spyOn<T, M extends Methods<Required<T>>>(
  obj: T,
  methodName: M,
  mock?: T[M]
): Required<T>[M] extends (...args: infer A) => infer R ? SpyImpl<A, R> : never
export function spyOn<T extends object, K extends string & keyof T>(
  obj: T,
  methodName: K | { getter: K } | { setter: K },
  mock?: Procedure
): SpyImpl<any[], any> {
  const spy = internalSpyOn(obj, methodName, mock)
  populateSpy(spy)
  ;(['restore', 'getOriginal', 'willCall'] as const).forEach((method) => {
    defineValue(spy, method, spy[SYMBOL_STATE][method])
  })
  return spy as any as SpyImpl
}

function isSpyFunction(obj: any): obj is SpyInternalImpl {
  return isMockFunction(obj) && 'getOriginal' in obj[SYMBOL_STATE]
}

import { createInternalSpy, populateSpy } from './internal.js'
import type { Spy } from './internal.js'

export interface SpyFn<A extends any[] = any[], R = any> extends Spy<A, R> {
  new (...args: A): R extends void ? any : R
  (...args: A): R
}

export function spy<A extends any[], R>(
  cb?: ((...args: A) => R) | { new (...args: A): R }
): SpyFn<A, R> {
  const spy = createInternalSpy(cb)
  populateSpy(spy)
  return spy as any
}

import { spies } from './internal.js'

export function restoreAll() {
  for (let fn of spies) {
    fn.restore()
  }
  spies.clear()
}

import { assert, define, defineValue, isPromise, isType } from './utils.js'
import { SYMBOL_STATE } from './constants.js'

interface GetState {
  <A extends any[], R>(spy: SpyInternalImpl<A, R>): SpyInternalImplState<A, R>
  <A extends any[], R>(spy: SpyInternal<A, R>): SpyInternalState<A, R>
}

export let spies = new Set<SpyImpl>()

let reset = (state: SpyInternalState) => {
  state.called = false
  state.callCount = 0
  state.calls = []
  state.results = []
  state.resolves = []
  state.next = []
}
let defineState = (spy: SpyInternal) => {
  define(spy, SYMBOL_STATE, {
    value: { reset: () => reset(spy[SYMBOL_STATE]) },
  })
  return spy[SYMBOL_STATE]
}
export let getInternalState: GetState = (spy) => {
  return (spy[SYMBOL_STATE] || defineState(spy)) as any
}

type ReturnError = ['error', any]
type ReturnOk<R> = ['ok', R]
type ResultFn<R> = ReturnError | ReturnOk<R>

export interface SpyInternal<A extends any[] = any[], R = any> {
  (this: any, ...args: A): R
  [SYMBOL_STATE]: SpyInternalState<A, R>
}

export interface SpyInternalImpl<A extends any[] = any[], R = any>
  extends SpyInternal<A, R> {
  [SYMBOL_STATE]: SpyInternalImplState<A, R>
}

interface SpyInternalState<A extends any[] = any[], R = any> {
  called: boolean
  callCount: number
  calls: A[]
  results: ResultFn<R>[]
  resolves: R extends PromiseLike<infer V> ? ResultFn<V>[] : never
  reset(): void
  impl: ((...args: A) => R) | undefined
  next: ResultFn<R>[]
}

interface SpyInternalImplState<A extends any[] = any[], R = any>
  extends SpyInternalState<A, R> {
  getOriginal(): (...args: A) => R
  willCall(cb: (...args: A) => R): this
  restore(): void
}

export interface Spy<A extends any[] = any[], R = any>
  extends SpyInternalState<A, R> {
  (this: any, ...args: A): R
  returns: R[]
  length: number
  nextError(error: any): this
  nextResult(result: R): this
}

export interface SpyImpl<A extends any[] = any[], R = any> extends Spy<A, R> {
  getOriginal(): (...args: A) => R
  willCall(cb: (...args: A) => R): this
  restore(): void
}

export function createInternalSpy<A extends any[], R>(
  cb?: ((...args: A) => R) | { new (...args: A): R }
): SpyInternal<A, R> {
  assert(
    isType('function', cb) || isType('undefined', cb),
    'cannot spy on a non-function value'
  )

  let fn = function (this: any, ...args: A) {
    const state = getInternalState(fn)
    state.called = true
    state.callCount++
    state.calls.push(args)
    const next = state.next.shift()
    if (next) {
      state.results.push(next)
      const [type, result] = next
      if (type === 'ok') {
        return result
      }
      throw result
    }
    // it can be thrown (anything can be thrown),
    // it can be a return value
    // it can be undefined, if there is no mocking function
    let result: any
    let type: 'ok' | 'error' = 'ok'
    const resultIndex = state.results.length
    if (state.impl) {
      try {
        if (new.target) {
          result = Reflect.construct(state.impl, args, new.target)
        } else {
          result = state.impl.apply(this, args)
        }
        type = 'ok'
      } catch (err: any) {
        result = err
        type = 'error'
        state.results.push([type, err])
        throw err
      }
    }
    let resultTuple: ResultFn<R> = [type, result]
    if (isPromise(result)) {
      result.then(
        (r: any) => (state.resolves[resultIndex] = ['ok', r]),
        (e: any) => (state.resolves[resultIndex] = ['error', e])
      )
    }
    state.results.push(resultTuple)
    return result
  } as SpyInternal<A, R>

  defineValue(fn, '_isMockFunction', true)
  defineValue(fn, 'length', cb ? cb.length : 0)
  defineValue(fn, 'name', cb ? cb.name || 'spy' : 'spy')

  const state = getInternalState(fn)
  state.reset()
  state.impl = cb as any

  return fn
}

export function isMockFunction(obj: any): obj is SpyInternal {
  return !!obj && obj._isMockFunction === true
}

export function populateSpy<A extends any[], R>(spy: SpyInternal<A, R>) {
  const state = getInternalState(spy)

  // already populated
  if ('returns' in spy) {
    return
  }

  define(spy, 'returns', {
    get: () => state.results.map(([, r]) => r),
  })
  ;(
    [
      'called',
      'callCount',
      'results',
      'resolves',
      'calls',
      'reset',
      'impl',
    ] as const
  ).forEach((n) =>
    define(spy, n, { get: () => state[n], set: (v) => (state[n] = v as never) })
  )
  defineValue(spy, 'nextError', (error: any) => {
    state.next.push(['error', error])
    return state
  })
  defineValue(spy, 'nextResult', (result: R) => {
    state.next.push(['ok', result])
    return state
  })
}

export function assert(condition: any, message: string): asserts condition {
  if (!condition) {
    throw new Error(message)
  }
}

export function isType(type: 'undefined', value: any): value is undefined
export function isType(type: 'function', value: any): value is () => void
export function isType(type: 'object', value: any): value is object
export function isType(type: 'string', value: any): value is string
export function isType(type: string, value: any) {
  return typeof value === type
}

export function isPromise(value: any) {
  return value instanceof Promise
}

export function define(
  obj: any,
  key: string | number | symbol,
  descriptor: PropertyDescriptor
) {
  Object.defineProperty(obj, key, descriptor)
}

export function defineValue(
  obj: any,
  key: string | number | symbol,
  value: unknown
) {
  define(obj, key, { value })
}

export function descriptors(obj: any) {
  return Object.getOwnPropertyDescriptors(obj)
}

import { describe, test, expect } from "vitest";
import { spyOn, spy } from "../src/index.ts";

describe("tinyspy regression", () => {
  test("spyOn mocks prototype method and restores cleanly", () => {
    class Foo { f() { return 'original'; } }
    const foo = new Foo();
    expect(foo.f()).toBe('original');
    const s = spyOn(foo, 'f');
    s.willCall(() => 'mocked');
    expect(foo.f()).toBe('mocked');
    s.restore();
    expect(foo.f()).toBe('original');
    expect(Object.getOwnPropertyDescriptor(foo, 'f')).toBeUndefined();
  });

  test("spy creates mock function with call tracking", () => {
    const fn = spy();
    expect(fn.called).toBe(false);
    expect(fn.callCount).toBe(0);
    fn('a', 'b');
    expect(fn.called).toBe(true);
    expect(fn.callCount).toBe(1);
    expect(fn.calls[0]).toEqual(['a', 'b']);
    fn.reset();
    expect(fn.called).toBe(false);
  });

  test("spyOn inherited getter preserves setter", () => {
    class Bar {
      _v = 'bar';
      get v(): string { return this._v; }
      set v(v: string) { this._v = v; }
    }
    class Foo extends Bar {}
    const foo = new Foo();
    const s = spyOn(foo, { getter: 'v' }, () => 'mocked');
    expect(foo.v).toBe('mocked');
    expect(() => { foo.v = 'test'; }).not.toThrow();
    expect(foo.v).toBe('mocked');
    s.restore();
    expect(foo.v).toBe('test');
  });
});

