// Minimal reproduction: spyOn leaking own property on prototype method restore
import { spyOn } from './src/index.ts'

class Foo {
  f() { return 'original'; }
}

const foo = new Foo()

console.log('Before spyOn:')
console.log('  foo.f():', foo.f())
console.log('  own property "f"?:', Object.getOwnPropertyDescriptor(foo, 'f'))

const s = spyOn(foo, 'f')
s.willCall(() => 'mocked')

console.log('\nAfter spyOn:')
console.log('  foo.f():', foo.f())
console.log('  own property "f"?:', Object.getOwnPropertyDescriptor(foo, 'f'))

s.restore()

console.log('\nAfter restore:')
console.log('  foo.f():', foo.f())
const ownDesc = Object.getOwnPropertyDescriptor(foo, 'f')
console.log('  own property "f"?:', ownDesc)

if (ownDesc !== undefined) {
  console.log('\n❌ BUG: own property "f" still exists after restore!')
  console.log('   This shadows the prototype method.')
  process.exit(1)
} else {
  console.log('\n✅ PASS: no own property, prototype method correctly restored')
  process.exit(0)
}

