import { describe, test, expect } from "vitest";
import { spyOn, spy, restoreAll } from "../src/index.ts";

describe("Phase 3: Invariant Tests", () => {
  // ──────────────────────────────────────────────
  // Core prototype spy/restore invariant
  // ──────────────────────────────────────────────
  describe("prototype method spy/restore", () => {
    test("no own property left after restore on plain object prototype", () => {
      const proto = { f() { return "proto"; } };
      const obj = Object.create(proto);
      const s = spyOn(obj, "f");
      expect(obj.f()).not.toBe("proto");
      s.restore();
      expect(obj.f()).toBe("proto");
      expect(Object.getOwnPropertyDescriptor(obj, "f")).toBeUndefined();
    });

    test("class instance prototype method restores cleanly", () => {
      class A { greet() { return "hello"; } }
      const a = new A();
      const s = spyOn(a, "greet");
      s.willCall(() => "mocked");
      expect(a.greet()).toBe("mocked");
      s.restore();
      expect(a.greet()).toBe("hello");
      expect(Object.getOwnPropertyDescriptor(a, "greet")).toBeUndefined();
    });

    test("multiple instances sharing prototype are not affected by spy", () => {
      class B { val() { return 1; } }
      const b1 = new B();
      const b2 = new B();
      const s = spyOn(b1, "val");
      expect(b1.val()).not.toBe(1);
      // b2 should still call the original (no interference)
      expect(b2.val()).toBe(1);
      s.restore();
      expect(b1.val()).toBe(1);
      expect(b2.val()).toBe(1);
    });

    test("deeply nested prototype chain restores correctly", () => {
      const grandparent = { method() { return "gp"; } };
      const parent = Object.create(grandparent);
      const child = Object.create(parent);
      const s = spyOn(child, "method");
      s.willCall(() => "mock");
      expect(child.method()).toBe("mock");
      s.restore();
      expect(child.method()).toBe("gp");
      expect(Object.getOwnPropertyDescriptor(child, "method")).toBeUndefined();
    });
  });

  // ──────────────────────────────────────────────
  // Own property spy/restore invariant
  // ──────────────────────────────────────────────
  describe("own method spy/restore", () => {
    test("own method is reassigned, not deleted", () => {
      const obj = { f() { return "own"; } };
      const s = spyOn(obj, "f");
      s.willCall(() => "mocked");
      expect(obj.f()).toBe("mocked");
      s.restore();
      expect(obj.f()).toBe("own");
      expect(Object.getOwnPropertyDescriptor(obj, "f")).toBeDefined();
    });

    test("configurable: false own property is reassigned", () => {
      const obj = {};
      Object.defineProperty(obj, "f", {
        value() { return "fixed"; },
        configurable: false,
        writable: false,
      });
      // spyOn should throw or handle non-configurable (depending on spec)
      // For now, ensure no crash
      try {
        const s = spyOn(obj, "f");
        s.willCall(() => "mocked");
        expect(obj.f()).toBe("mocked");
        s.restore();
      } catch {
        // acceptable if non-configurable throws
      }
    });
  });

  // ──────────────────────────────────────────────
  // Getter / Setter spy/restore invariants
  // ──────────────────────────────────────────────
  describe("getter/setter spy/restore", () => {
    test("getter spy restores prototype getter", () => {
      const proto = { get x() { return 42; } };
      const obj = Object.create(proto);
      const s = spyOn(obj, { getter: "x" }, () => 100);
      expect(obj.x).toBe(100);
      s.restore();
      expect(obj.x).toBe(42);
      expect(Object.getOwnPropertyDescriptor(obj, "x")).toBeUndefined();
    });

    test("setter spy restores prototype setter", () => {
      let captured: any;
      const proto = {
        get x() { return captured; },
        set x(v) { captured = v; },
      };
      const obj = Object.create(proto);
      obj.x = "original";
      const s = spyOn(obj, { setter: "x" }, (v) => { captured = "mock:" + v; });
      obj.x = "test";
      expect(captured).toBe("mock:test");
      s.restore();
      obj.x = "restored";
      expect(captured).toBe("restored");
    });

    test("inherited getter preserves setter (from existing test)", () => {
      class Bar {
        _v = "bar";
        get v(): string { return this._v; }
        set v(v: string) { this._v = v; }
      }
      class Foo extends Bar {}
      const foo = new Foo();
      const s = spyOn(foo, { getter: "v" }, () => "mocked");
      expect(foo.v).toBe("mocked");
      expect(() => { foo.v = "test"; }).not.toThrow();
      expect(foo.v).toBe("mocked");
      s.restore();
      expect(foo.v).toBe("test");
    });
  });

  // ──────────────────────────────────────────────
  // Async / concurrent spy invariants
  // ──────────────────────────────────────────────
  describe("async spy invariants", () => {
    test("spy intercepts async method calls", async () => {
      class C {
        async compute() { return 1; }
      }
      const c = new C();
      const s = spyOn(c, "compute");
      s.willCall(async () => 99);
      const result = await c.compute();
      expect(result).toBe(99);
      s.restore();
      const result2 = await c.compute();
      expect(result2).toBe(1);
    });

    test("concurrent spy/restores don't interfere", async () => {
      class D { val() { return "d"; } }
      const d1 = new D();
      const d2 = new D();
      const s1 = spyOn(d1, "val");
      const s2 = spyOn(d2, "val");
      s1.willCall(() => "m1");
      s2.willCall(() => "m2");
      expect(d1.val()).toBe("m1");
      expect(d2.val()).toBe("m2");
      s1.restore();
      expect(d1.val()).toBe("d");
      expect(d2.val()).toBe("m2");
      s2.restore();
      expect(d2.val()).toBe("d");
    });
  });

  // ──────────────────────────────────────────────
  // restoreAll invariant
  // ──────────────────────────────────────────────
  describe("restoreAll", () => {
    test("restoreAll clears all spies and restores prototype methods", () => {
      class E { run() { return "e"; } }
      const e1 = new E();
      const e2 = new E();
      spyOn(e1, "run");
      spyOn(e2, "run");
      restoreAll();
      expect(e1.run()).toBe("e");
      expect(e2.run()).toBe("e");
      expect(Object.getOwnPropertyDescriptor(e1, "run")).toBeUndefined();
      expect(Object.getOwnPropertyDescriptor(e2, "run")).toBeUndefined();
    });
  });

  // ──────────────────────────────────────────────
  // Null / empty edge cases
  // ──────────────────────────────────────────────
  describe("edge cases", () => {
    test("spyOn method named 'toString' on prototype", () => {
      const proto = { toString() { return "custom"; } };
      const obj = Object.create(proto);
      const s = spyOn(obj, "toString");
      s.willCall(() => "mocked");
      expect(obj.toString()).toBe("mocked");
      s.restore();
      expect(obj.toString()).toBe("custom");
      expect(Object.getOwnPropertyDescriptor(obj, "toString")).toBeUndefined();
    });

    test("spyOn symbol-keyed prototype method", () => {
      const sym = Symbol("test");
      const proto = { [sym]() { return "sym-proto"; } };
      const obj = Object.create(proto);
      const s = spyOn(obj, sym as any);
      s.willCall(() => "sym-mock");
      expect(obj[sym]()).toBe("sym-mock");
      s.restore();
      expect(obj[sym]()).toBe("sym-proto");
      expect(Object.getOwnPropertyDescriptor(obj, sym)).toBeUndefined();
    });

    test("spy on prototype, restore, then spy again works correctly", () => {
      class F { m() { return "f"; } }
      const f = new F();
      const s1 = spyOn(f, "m");
      s1.willCall(() => "first");
      expect(f.m()).toBe("first");
      s1.restore();
      expect(f.m()).toBe("f");
      expect(Object.getOwnPropertyDescriptor(f, "m")).toBeUndefined();

      const s2 = spyOn(f, "m");
      s2.willCall(() => "second");
      expect(f.m()).toBe("second");
      s2.restore();
      expect(f.m()).toBe("f");
      expect(Object.getOwnPropertyDescriptor(f, "m")).toBeUndefined();
    });

    test("restoring a spy that was never called", () => {
      class G { idle() { return "idle"; } }
      const g = new G();
      const s = spyOn(g, "idle");
      // never called
      s.restore();
      expect(g.idle()).toBe("idle");
      expect(Object.getOwnPropertyDescriptor(g, "idle")).toBeUndefined();
    });
  });
});

